import json

import urban_micro
from urban_micro import (
    hotspot_plan,
    hotspot_kind_summary,
    hotspot_kind_priority,
    hotspot_kind_portfolio,
)
from urban_micro import uhi as _uhi

assert "hotspot_kind_portfolio" in urban_micro.__all__
assert urban_micro.hotspot_kind_portfolio is hotspot_kind_portfolio


def _priority(specs, alpha=0.5):
    hotspots, effects = [], {}
    for index, (pick, by, key, effect, q) in enumerate(specs):
        hotspots.append(
            '{"pick":'
            + json.dumps(list(pick), separators=(",", ":"))
            + f',"by":"{by}","key":"{key}","steps":10,"hits":10,'
            + f'"max_abs":{index + 1},"persistence":1.000000}}'
        )
        effects[(tuple(pick), by, key)] = (effect, q)
    rank = f'{{"alpha":{alpha:.6f},"hotspots":[{",".join(hotspots)}]}}\n'
    return _uhi.rank_hotspot_priority(rank, effects)


# 2 coherent region panels, both carrying green (n=2 -> p=0.5, rejects at
# alpha 0.5); one window panel carrying roof (p=1 -> not eligible).
specs = []
for i in range(2):
    specs.append((("green",), "region", f"R{i}", -2.0, 0.01))
specs.append((("roof",), "window", "W1", -1.0, 0.9))
priority = _priority(specs)
plan = hotspot_plan(
    priority,
    {("green",): 1.0, ("roof",): 2.0},
    **{
        "limit": {
            ("region", "R0"): 9.0,
            ("region", "R1"): 9.0,
            ("window", "W1"): 9.0,
        },
        "allow": {
            ("region", "R0"): [["green"]],
            ("region", "R1"): [["green"]],
            ("window", "W1"): [["roof"]],
        },
    },
)
effects = {
    ("region", "R0"): (10.0, {("green",): -2.0}),
    ("region", "R1"): (10.0, {("green",): -2.0}),
    ("window", "W1"): (8.0, {("roof",): -1.0}),
}
impact = hotspot_plan_impact(plan, effects)
kind_effects = {
    ("region", "R0", ("green",)): -2.0,
    ("region", "R1", ("green",)): -2.0,
    ("window", "W1", ("roof",)): -1.0,
}
summary = hotspot_kind_summary(
    impact,
    kind_effects,
    {
        ("region", "R0"): 1.0,
        ("region", "R1"): 1.0,
        ("window", "W1"): 1.0,
    },
)
prio = hotspot_kind_priority(
    summary, {"green": 1.0, "roof": 2.0}
)
print(prio)
out = hotspot_kind_portfolio(
    prio,
    {"region": 1.0, "window": 9.0},
    {"region": ["green"], "window": ["roof"]},
)
print(out)
groups = {g["by"]: g for g in json.loads(out)["groups"]}
# green: change -2, cost 1 -> score 2, eligible -> picked
assert groups["region"]["pick"] == ["green"]
assert groups["region"]["score"] == 2.0
assert groups["region"]["skip"] == []
# roof not eligible -> reason q even though budget allows it
assert groups["window"]["pick"] == []
assert groups["window"]["skip"] == [{"kind": "roof", "reason": "q"}]
assert groups["window"]["remaining"] == 9.0
print("end-to-end OK")

